const maxWrapWidth = 30

var (
	ansiRe    = regexp.MustCompile("\033\\[(?:[0-9]{1,3}(?:;[0-9]{1,3})*)?[m|K]")
	decimalRe = regexp.MustCompile(`^-?(?:\d{1,3}(?:,\d{3})*|\d+)(?:\.\d+)?$`)
)

type entry struct {
	cells     [][]string // every cell split in lines
	separator bool
}

// Table accumulates rows and renders them with one of the supported modes.
type Table struct {
	out         io.Writer
	mode        Mode
	header      [][]string
	headerSet   bool
	entries     []entry
	widths      map[int]int
	rowCount    int
	wrap        bool
	headerAlign int
	cellAlign   int
	colSep      string
	rowSep      string
	centerSep   string
	padding     string
	compact     bool
	borderTop   bool
	borderLeft  bool
	borderRight bool
	headerLine  bool
}

// NewTable creates a table writing to out with the given mode.
func NewTable(out io.Writer, mode Mode) *Table {
	t := &Table{
		out:         out,
		mode:        mode,
		widths:      map[int]int{},
		wrap:        true,
		headerAlign: alignDefault,
		cellAlign:   alignDefault,
		colSep:      "|",
		rowSep:      "-",
		centerSep:   "+",
		padding:     "\t",
		borderTop:   true,
		borderLeft:  true,
		borderRight: true,
		headerLine:  true,
	}

	switch mode {
	case ModeMarkdown:
		t.wrap = false
		t.centerSep = "|"
		t.borderTop = false
	case ModeRaw:
		t.wrap = false
		t.headerAlign = alignLeft
		t.cellAlign = alignLeft
		t.colSep = ""
		t.rowSep = ""
		t.centerSep = ""
		t.compact = true
		t.borderTop = false
		t.borderLeft = false
		t.borderRight = false
		t.headerLine = false
	}

	return t
}

// SetHeader defines the column titles.
func (t *Table) SetHeader(keys []string) {
	for i, k := range keys {
		t.header = append(t.header, t.measure(k, i))
	}
	t.headerSet = true
}

// Append adds a row of cells.
func (t *Table) Append(row []string) {
	cells := make([][]string, 0, len(row))
	for i, v := range row {
		cells = append(cells, t.measure(v, i))
	}
	t.entries = append(t.entries, entry{cells: cells})
	t.rowCount++
}

// Separator marks the end of a group of rows. Separators are drawn in the
// bordered and markdown modes.
func (t *Table) Separator() {
	t.entries = append(t.entries, entry{separator: true})
}

// NumRows returns the amount of rows appended so far.
func (t *Table) NumRows() int {
	return t.rowCount
}

// measure splits a value in lines (wrapping them when enabled) and records
// the resulting column width.
func (t *Table) measure(value string, col int) []string {
	lines := strings.Split(value, "\n")
	width := 0
	for _, l := range lines {
		if w := displayWidth(l); w > width {
			width = w
		}
	}

	if t.wrap {
		if width > maxWrapWidth {
			width = maxWrapWidth
		}
		newWidth := width
		wrapped := make([]string, 0, len(lines))
		// every paragraph gets reflowed individually
		for i, para := range lines {
			paraLines := wrapText(para, width)
			for _, l := range paraLines {
				if w := displayWidth(l); w > newWidth {
					newWidth = w
				}
			}
			if i > 0 {
				wrapped = append(wrapped, " ")
			}
			wrapped = append(wrapped, paraLines...)
		}
		lines = wrapped
		width = newWidth
	}

	if cur, ok := t.widths[col]; !ok || cur < width || cur == 0 {
		t.widths[col] = width
	}

	return lines
}

// Render writes the table.
func (t *Table) Render() {
	if t.borderTop {
		t.printLine()
	}
	t.printHeader()

	groups := t.groups()
	for i, g := range groups {
		for _, row := range g {
			t.printRow(row)
		}
		switch t.mode {
		case ModeTable:
			t.printLine()
		case ModeMarkdown:
			if i < len(groups)-1 {
				t.printLine()
			}
		}
	}
}

// groups splits the entries in blocks of rows delimited by separators,
// dropping empty blocks.
func (t *Table) groups() [][][][]string {
	var (
		groups  [][][][]string
		current [][][]string
	)
	flush := func() {
		if len(current) > 0 {
			groups = append(groups, current)
		}
		current = nil
	}
	for _, e := range t.entries {
		if e.separator {
			flush()
			continue
		}
		current = append(current, e.cells)
	}
	flush()
	return groups
}

func (t *Table) columnCount() int {
	return len(t.widths)
}

func (t *Table) printLine() {
	fmt.Fprint(t.out, t.centerSep)
	for i := 0; i < t.columnCount(); i++ {
		w := t.widths[i]
		fmt.Fprintf(t.out, "%s%s%s%s", t.rowSep, strings.Repeat(t.rowSep, w), t.rowSep, t.centerSep)
	}
	fmt.Fprint(t.out, "\n")
}

func (t *Table) printHeader() {
	if !t.headerSet || len(t.header) == 0 {
		return
	}

	end := t.columnCount() - 1
	height := 0
	for _, h := range t.header {
		if len(h) > height {
			height = len(h)
		}
	}

	for x := 0; x < height; x++ {
		if !t.compact {
			fmt.Fprint(t.out, conditional(t.borderLeft, t.colSep, t.centerSep))
		}
		for y := 0; y <= end; y++ {
			h := ""
			if y < len(t.header) && x < len(t.header[y]) {
				h = t.header[y][x]
			}
			h = formatTitle(h)

			var pad string
			if t.compact {
				pad = conditional(y == end && !t.borderLeft, " ", t.padding)
			} else {
				pad = conditional(y == end && !t.borderLeft, " ", t.colSep)
			}

			text := align(h, t.widths[y], t.headerAlign, true)
			if t.compact {
				fmt.Fprintf(t.out, "%s%s", text, pad)
			} else {
				fmt.Fprintf(t.out, " %s %s", text, pad)
			}
		}
		fmt.Fprint(t.out, "\n")
	}

	if t.headerLine {
		t.printLine()
	}
}

func (t *Table) printRow(cells [][]string) {
	height := 0
	for _, c := range cells {
		if len(c) > height {
			height = len(c)
		}
	}

	for x := 0; x < height; x++ {
		for y, c := range cells {
			if !t.compact {
				fmt.Fprint(t.out, conditional(!t.borderLeft && y == 0, " ", t.colSep))
				fmt.Fprint(t.out, " ")
			}

			str := "  "
			if x < len(c) {
				str = c[x]
			}

			fmt.Fprint(t.out, align(str, t.widths[y], t.cellAlign, false))

			if t.compact {
				fmt.Fprint(t.out, t.padding)
			} else {
				fmt.Fprint(t.out, " ")
			}
		}
		if !t.compact {
			fmt.Fprint(t.out, conditional(t.borderLeft, t.colSep, " "))
		}
		fmt.Fprint(t.out, "\n")
	}
}

// align pads s to width following the requested alignment. Header cells use
// centering by default while body cells right-align numbers.
func align(s string, width, mode int, header bool) string {
	switch mode {
	case alignCenter:
		return padCenter(s, width)
	case alignRight:
		return padLeft(s, width)
	case alignLeft:
		return padRight(s, width)
	}
	if header {
		return padCenter(s, width)
	}
	if decimalRe.MatchString(strings.TrimSpace(s)) {
		return padLeft(s, width)
	}
	return padRight(s, width)
}

func conditional(cond bool, valid, inValid string) string {
	if cond {
		return valid
	}
	return inValid
}

func displayWidth(s string) int {
	return runewidth.StringWidth(ansiRe.ReplaceAllLiteralString(s, ""))
}

func padCenter(s string, width int) string {
	gap := width - displayWidth(s)
	if gap > 0 {
		left := int(math.Ceil(float64(gap / 2)))
		right := gap - left
		return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
	}
	return s
}

func padRight(s string, width int) string {
	gap := width - displayWidth(s)
	if gap > 0 {
		return s + strings.Repeat(" ", gap)
	}
	return s
}

func padLeft(s string, width int) string {
	gap := width - displayWidth(s)
	if gap > 0 {
		return strings.Repeat(" ", gap) + s
	}
	return s
}

// formatTitle normalizes a header: underscores and dots become spaces and
// the result is upper-cased.
func formatTitle(name string) string {
	origLen := len(name)
	rs := []rune(name)
	for i, r := range rs {
		switch r {
		case '_':
			rs[i] = ' '
		case '.':
			// keep dots that look like decimal separators
			if (i != 0 && !isNumOrSpace(rs[i-1])) || (i != len(rs)-1 && !isNumOrSpace(rs[i+1])) {
				rs[i] = ' '
			}
		}
	}
	name = strings.TrimSpace(string(rs))
	if len(name) == 0 && origLen > 0 {
		name = " "
	}
	return strings.ToUpper(name)
}

func isNumOrSpace(r rune) bool {
	return ('0' <= r && r <= '9') || r == ' '
}

// wrapText breaks a paragraph into lines no longer than limit (unless a
// single word exceeds it), minimizing the raggedness of the lines.
func wrapText(s string, limit int) []string {
	words := strings.Split(strings.ReplaceAll(s, "\n", " "), " ")
	for _, w := range words {
		if l := runewidth.StringWidth(w); l > limit {
			limit = l
		}
	}

	var lines []string
	for _, group := range breakWords(words, 1, limit, 100000) {
		lines = append(lines, strings.Join(group, " "))
	}
	return lines
}

// breakWords distributes words in lines using a dynamic programming approach
// that penalizes the squared trailing gap of every line (classic minimum
// raggedness algorithm).
func breakWords(words []string, space, limit, penalty int) [][]string {
	n := len(words)

	length := make([][]int, n)
	for i := 0; i < n; i++ {
		length[i] = make([]int, n)
		length[i][i] = runewidth.StringWidth(words[i])
		for j := i + 1; j < n; j++ {
			length[i][j] = length[i][j-1] + space + runewidth.StringWidth(words[j])
		}
	}

	next := make([]int, n)
	cost := make([]int, n)
	for i := range cost {
		cost[i] = math.MaxInt32
	}

	for i := n - 1; i >= 0; i-- {
		if length[i][n-1] <= limit {
			cost[i] = 0
			next[i] = n
			continue
		}
		for j := i + 1; j < n; j++ {
			d := limit - length[i][j-1]
			c := d*d + cost[j]
			if length[i][j-1] > limit {
				c += penalty
			}
			if c < cost[i] {
				cost[i] = c
				next[i] = j
			}
		}
	}

	var lines [][]string
	for i := 0; i < n; {
		lines = append(lines, words[i:next[i]])
		i = next[i]
	}
	return lines
}
EOF
