// Package hosts models the content of a hosts file: the untouched default
// section plus the profiles managed by this tool.
package hosts

import (
	"errors"
	"fmt"
	"net"
	"strings"
)

// Status of a profile.
type Status string

const (
	// Enabled means the profile lines are active.
	Enabled Status = "on"
	// Disabled means the profile lines are commented out.
	Disabled Status = "off"
)

// DefaultName is the reserved name of the unmanaged section.
const DefaultName = "default"

// Banner is written between the default section and the managed profiles.
const Banner = `##################################################################
# Content under this line is handled by hostctl. DO NOT EDIT.
##################################################################
`

// bannerMarker identifies lines belonging to a previously written banner.
const bannerMarker = "# Content under this line is handled by hostctl. DO NOT EDIT."

var (
	// ErrDefaultProfile is returned when trying to manage the default section.
	ErrDefaultProfile = errors.New("'default' profile should not be handled by hostctl")
	// ErrUnknownProfile is returned when a profile name does not exist.
	ErrUnknownProfile = errors.New("unknown profile name")
	// ErrNoProfiles is returned when an operation needs at least one profile.
	ErrNoProfiles = errors.New("there are no profiles")
	// ErrMissingProfile is returned when a command lacks the profile argument.
	ErrMissingProfile = errors.New("missing profile name")
	// ErrOnlyOneProfile is returned when more than one profile is given.
	ErrOnlyOneProfile = errors.New("specify only one profile")
	// ErrArgsWithAll is returned when --all is combined with arguments.
	ErrArgsWithAll = errors.New("args must be empty with --all flag")
)

// Route groups the host names pointing to the same IP.
type Route struct {
	IP        net.IP
	HostNames []string
}

// Profile is a named group of routes that can be switched on and off.
type Profile struct {
	Name   string
	Status Status
	IPList []string
	Routes map[string]*Route
}

// NewProfile creates an empty enabled profile.
func NewProfile(name string) *Profile {
	return &Profile{
		Name:   name,
		Status: Enabled,
		Routes: map[string]*Route{},
	}
}

// AddRoute registers host names for an IP, keeping insertion order and
// avoiding duplicated names.
func (p *Profile) AddRoute(ip net.IP, hostnames ...string) {
	key := ip.String()
	if p.Routes == nil {
		p.Routes = map[string]*Route{}
	}
	route, ok := p.Routes[key]
	if !ok {
		route = &Route{IP: ip}
		p.Routes[key] = route
		p.IPList = append(p.IPList, key)
	}
	for _, h := range hostnames {
		if !containsString(route.HostNames, h) {
			route.HostNames = append(route.HostNames, h)
		}
	}
}

// AddRoutes merges all the routes of another profile.
func (p *Profile) AddRoutes(other *Profile) {
	for _, key := range other.IPList {
		r := other.Routes[key]
		p.AddRoute(r.IP, r.HostNames...)
	}
}

// RemoveHostnames drops the given host names from every route, removing the
// routes that end up empty.
func (p *Profile) RemoveHostnames(hostnames []string) {
	var keep []string
	for _, key := range p.IPList {
		route := p.Routes[key]
		var names []string
		for _, h := range route.HostNames {
			if !containsString(hostnames, h) {
				names = append(names, h)
			}
		}
		if len(names) == 0 {
			delete(p.Routes, key)
			continue
		}
		route.HostNames = names
		keep = append(keep, key)
	}
	p.IPList = keep
}

// IsEmpty reports whether the profile has no routes left.
func (p *Profile) IsEmpty() bool {
	return len(p.Routes) == 0
}

// Render writes the profile in hosts file syntax.
func (p *Profile) Render(sb *strings.Builder) {
	fmt.Fprintf(sb, "# profile.%s %s\n", p.Status, p.Name)
	for _, key := range p.IPList {
		route := p.Routes[key]
		for _, h := range route.HostNames {
			if p.Status == Disabled {
				sb.WriteString("# ")
			}
			fmt.Fprintf(sb, "%s %s\n", route.IP, h)
		}
	}
	sb.WriteString("# end\n")
}

// Line is an entry of the default (unmanaged) section.
type Line struct {
	Raw      string // verbatim content for comments/unknown lines
	IP       net.IP
	Host     string
	Disabled bool
	IsRoute  bool
}

// Render returns the textual form of the line.
func (l *Line) Render() string {
	if !l.IsRoute {
		return l.Raw
	}
	prefix := ""
	if l.Disabled {
		prefix = "# "
	}
	return fmt.Sprintf("%s%s %s", prefix, l.IP, l.Host)
}

// Status of the line as shown on listings.
func (l *Line) Status() Status {
	if l.Disabled {
		return Disabled
	}
	return Enabled
}

// Content is the parsed representation of a hosts file.
type Content struct {
	DefaultLines []*Line
	ProfileNames []string
	Profiles     map[string]*Profile
}

// NewContent creates an empty content.
func NewContent() *Content {
	return &Content{Profiles: map[string]*Profile{}}
}

func containsString(list []string, s string) bool {
	for _, v := range list {
		if v == s {
			return true
		}
	}
	return false
}
