package hosts

import (
	"bufio"
	"io"
	"net"
	"regexp"
	"strings"
	"unicode"
)

var (
	profileHeaderRe = regexp.MustCompile(`# profile\.(on|off)\s+([a-z0-9\s_.-]+)`)
	profileEndRe    = regexp.MustCompile(`(?i)# end`)
)

// Parse reads a hosts file splitting the unmanaged lines from the profiles.
func Parse(r io.Reader) *Content {
	content := NewContent()
	current := ""

	scanner := bufio.NewScanner(r)
	for scanner.Scan() {
		line := scanner.Text()

		if m := profileHeaderRe.FindStringSubmatch(line); m != nil {
			name := strings.TrimSpace(m[2])
			p := NewProfile(name)
			if m[1] == "off" {
				p.Status = Disabled
			}
			content.ProfileNames = append(content.ProfileNames, name)
			content.Profiles[name] = p
			current = name
			continue
		}

		if profileEndRe.MatchString(line) {
			current = ""
			continue
		}

		if current == "" {
			if strings.Contains(line, bannerMarker) {
				// the banner is surrounded by its decoration lines
				content.DefaultLines = content.DefaultLines[:len(content.DefaultLines)-1]
				scanner.Scan()
				continue
			}
			content.DefaultLines = append(content.DefaultLines, parseDefaultLine(line))
			continue
		}

		if ip, hosts, _, ok := parseRoute(line); ok {
			content.Profiles[current].AddRoute(ip, hosts...)
		}
	}

	return content
}

// ParseProfile reads routes from a reader ignoring any profile markers.
func ParseProfile(name string, r io.Reader) *Profile {
	p := NewProfile(name)
	scanner := bufio.NewScanner(r)
	for scanner.Scan() {
		if ip, hosts, _, ok := parseRoute(scanner.Text()); ok {
			p.AddRoute(ip, hosts...)
		}
	}
	return p
}

func parseDefaultLine(line string) *Line {
	trimmed := strings.TrimSpace(line)
	if ip, hosts, disabled, ok := parseRoute(trimmed); ok {
		return &Line{IP: ip, Host: hosts[0], Disabled: disabled, IsRoute: true}
	}
	return &Line{Raw: trimmed}
}

// parseRoute extracts the IP and host names of a hosts line. Lines commented
// with "# " are accepted and flagged as disabled. Inline comments are dropped.
func parseRoute(line string) (net.IP, []string, bool, bool) {
	s := strings.TrimSpace(line)
	disabled := false

	if strings.HasPrefix(s, "#") {
		rest := s[1:]
		if rest == "" || !unicode.IsSpace(rune(rest[0])) {
			return nil, nil, false, false
		}
		s = strings.TrimSpace(rest)
		disabled = true
	}

	if i := strings.IndexByte(s, '#'); i >= 0 {
		s = s[:i]
	}

	fields := strings.Fields(s)
	if len(fields) < 2 {
		return nil, nil, false, false
	}

	ip := net.ParseIP(fields[0])
	if ip == nil {
		return nil, nil, false, false
	}

	return ip, fields[1:], disabled, true
}
