package hosts

import (
	"strings"
)

// Render produces the full hosts file text.
func (c *Content) Render() string {
	var sb strings.Builder

	for _, l := range collapseBlankLines(c.DefaultLines) {
		sb.WriteString(l)
		sb.WriteString("\n")
	}

	sb.WriteString("\n")
	sb.WriteString(Banner)

	for _, name := range c.ProfileNames {
		if name == DefaultName {
			continue
		}
		p, ok := c.Profiles[name]
		if !ok {
			continue
		}
		sb.WriteString("\n")
		p.Render(&sb)
	}

	return sb.String()
}

// collapseBlankLines renders the default lines merging consecutive empty
// lines and dropping the trailing ones.
func collapseBlankLines(lines []*Line) []string {
	var out []string
	lastBlank := false
	for _, l := range lines {
		text := l.Render()
		if text == "" {
			if lastBlank {
				continue
			}
			lastBlank = true
		} else {
			lastBlank = false
		}
		out = append(out, text)
	}
	for len(out) > 0 && out[len(out)-1] == "" {
		out = out[:len(out)-1]
	}
	return out
}

// GetProfile returns a managed profile by name.
func (c *Content) GetProfile(name string) (*Profile, bool) {
	p, ok := c.Profiles[name]
	return p, ok
}

// HasProfile reports whether a managed profile exists.
func (c *Content) HasProfile(name string) bool {
	_, ok := c.Profiles[name]
	return ok
}

// AddProfile merges the profile into an existing one with the same name or
// appends it as a new profile.
func (c *Content) AddProfile(p *Profile) {
	if existing, ok := c.Profiles[p.Name]; ok {
		existing.AddRoutes(p)
		return
	}
	c.appendProfile(p)
}

// ReplaceProfile overwrites the routes of a profile (or adds it) and leaves it
// enabled.
func (c *Content) ReplaceProfile(p *Profile) {
	p.Status = Enabled
	if _, ok := c.Profiles[p.Name]; ok {
		c.Profiles[p.Name] = p
		return
	}
	c.appendProfile(p)
}

func (c *Content) appendProfile(p *Profile) {
	c.ProfileNames = append(c.ProfileNames, p.Name)
	c.Profiles[p.Name] = p
}

// AddRoutes adds host names to a profile, creating it when needed.
func (c *Content) AddRoutes(name string, from *Profile) {
	p, ok := c.Profiles[name]
	if !ok {
		p = NewProfile(name)
		c.appendProfile(p)
	}
	p.AddRoutes(from)
}

// RemoveHostnames removes host names from a profile. The profile itself is
// removed when it ends up empty, which is reported in the returned flag.
func (c *Content) RemoveHostnames(name string, hostnames []string) (bool, error) {
	p, ok := c.Profiles[name]
	if !ok {
		return false, ErrUnknownProfile
	}
	p.RemoveHostnames(hostnames)
	if p.IsEmpty() {
		return true, c.RemoveProfile(name)
	}
	return false, nil
}

// RemoveProfile deletes a profile and every reference to its name.
func (c *Content) RemoveProfile(name string) error {
	if name == DefaultName {
		return ErrDefaultProfile
	}
	if _, ok := c.Profiles[name]; !ok {
		return ErrUnknownProfile
	}
	delete(c.Profiles, name)
	var names []string
	for _, n := range c.ProfileNames {
		if n != name {
			names = append(names, n)
		}
	}
	c.ProfileNames = names
	return nil
}

// RemoveProfiles deletes several profiles.
func (c *Content) RemoveProfiles(names []string) error {
	for _, n := range names {
		if err := c.RemoveProfile(n); err != nil {
			return err
		}
	}
	return nil
}

// SetStatus changes the status of the given profiles.
func (c *Content) SetStatus(names []string, status Status) error {
	for _, n := range names {
		p, ok := c.Profiles[n]
		if !ok {
			return ErrUnknownProfile
		}
		p.Status = status
	}
	return nil
}

// SetStatusAll changes the status of every profile.
func (c *Content) SetStatusAll(status Status) {
	for _, p := range c.Profiles {
		p.Status = status
	}
}

// SetStatusOnly sets the status of the given profiles and the opposite one to
// the rest.
func (c *Content) SetStatusOnly(names []string, status Status) {
	other := Disabled
	if status == Disabled {
		other = Enabled
	}
	for name, p := range c.Profiles {
		if containsString(names, name) {
			p.Status = status
		} else {
			p.Status = other
		}
	}
}

// Toggle flips the status of the given profiles.
func (c *Content) Toggle(names []string) error {
	for _, n := range names {
		p, ok := c.Profiles[n]
		if !ok {
			return ErrUnknownProfile
		}
		if p.Status == Enabled {
			p.Status = Disabled
		} else {
			p.Status = Enabled
		}
	}
	return nil
}
EOF
