// Package docker is a tiny client for the Docker Engine HTTP API covering the
// calls needed to sync container IPs.
package docker

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/url"
	"os"
	"strings"
	"time"
)

const (
	defaultHost       = "unix:///var/run/docker.sock"
	defaultAPIVersion = "1.42"
)

// Client talks to a Docker daemon.
type Client struct {
	host    string
	proto   string
	addr    string
	version string
	http    *http.Client
}

// Container is the subset of the container summary used by the tool.
type Container struct {
	ID              string           `json:"Id"`
	Names           []string         `json:"Names"`
	NetworkSettings *NetworkSettings `json:"NetworkSettings"`
}

// NetworkSettings holds the networks a container is attached to.
type NetworkSettings struct {
	Networks map[string]*EndpointSettings `json:"Networks"`
}

// EndpointSettings is the attachment of a container to one network.
type EndpointSettings struct {
	NetworkID string `json:"NetworkID"`
	IPAddress string `json:"IPAddress"`
}

// Network is the subset of a network resource used by the tool.
type Network struct {
	Name string `json:"Name"`
	ID   string `json:"Id"`
}

// Filters is the structure the API expects in the "filters" query parameter.
type Filters map[string]map[string]bool

// Add registers a filter value.
func (f Filters) Add(key, value string) {
	if f[key] == nil {
		f[key] = map[string]bool{}
	}
	f[key][value] = true
}

// NewClientFromEnv builds a client honoring DOCKER_HOST and
// DOCKER_API_VERSION.
func NewClientFromEnv() (*Client, error) {
	host := os.Getenv("DOCKER_HOST")
	if host == "" {
		host = defaultHost
	}

	proto, addr, err := parseHost(host)
	if err != nil {
		return nil, err
	}

	version := os.Getenv("DOCKER_API_VERSION")
	if version == "" {
		version = defaultAPIVersion
	}

	c := &Client{host: host, proto: proto, addr: addr, version: version}

	transport := &http.Transport{}
	switch proto {
	case "unix":
		transport.DialContext = func(ctx context.Context, _, _ string) (net.Conn, error) {
			return (&net.Dialer{Timeout: 32 * time.Second}).DialContext(ctx, "unix", addr)
		}
	default:
		transport.DialContext = (&net.Dialer{Timeout: 32 * time.Second}).DialContext
	}
	c.http = &http.Client{Transport: transport}

	return c, nil
}

func parseHost(host string) (string, string, error) {
	parts := strings.SplitN(host, "://", 2)
	if len(parts) != 2 || parts[0] == "" {
		return "", "", fmt.Errorf("unable to parse docker host `%s`", host)
	}

	proto, addr := parts[0], parts[1]
	if proto == "tcp" {
		u, err := url.Parse(host)
		if err != nil {
			return "", "", err
		}
		addr = u.Host
	}

	return proto, addr, nil
}

// ListContainers returns the containers matching the filters.
func (c *Client) ListContainers(ctx context.Context, filters Filters) ([]Container, error) {
	query := url.Values{}
	if len(filters) > 0 {
		data, err := json.Marshal(filters)
		if err != nil {
			return nil, err
		}
		query.Set("filters", string(data))
	}

	var containers []Container
	if err := c.get(ctx, "/containers/json", query, &containers); err != nil {
		return nil, err
	}
	return containers, nil
}

// ListNetworks returns every network known to the daemon.
func (c *Client) ListNetworks(ctx context.Context) ([]Network, error) {
	var networks []Network
	if err := c.get(ctx, "/networks", nil, &networks); err != nil {
		return nil, err
	}
	return networks, nil
}

func (c *Client) get(ctx context.Context, path string, query url.Values, out interface{}) error {
	u := &url.URL{Scheme: "http", Path: fmt.Sprintf("/v%s%s", c.version, path)}
	if c.proto == "tcp" {
		u.Host = c.addr
	} else {
		u.Host = "docker"
	}
	if len(query) > 0 {
		u.RawQuery = query.Encode()
	}

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
	if err != nil {
		return err
	}
	if c.proto != "tcp" {
		req.Host = "docker"
	}

	resp, err := c.http.Do(req)
	if err != nil {
		return c.connectionError(err)
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return err
	}

	if resp.StatusCode < 200 || resp.StatusCode >= 400 {
		return c.daemonError(resp, body)
	}

	return json.Unmarshal(body, out)
}

func (c *Client) connectionError(err error) error {
	var netErr net.Error
	if errors.As(err, &netErr) {
		msg := err.Error()
		if netErr.Timeout() || strings.Contains(msg, "connection refused") || strings.Contains(msg, "dial unix") {
			return fmt.Errorf("Cannot connect to the Docker daemon at %s. Is the docker daemon running?", c.host)
		}
	}
	var urlErr *url.Error
	if errors.As(err, &urlErr) {
		msg := err.Error()
		if strings.Contains(msg, "connection refused") || strings.Contains(msg, "dial unix") || strings.Contains(msg, "no such file") {
			return fmt.Errorf("Cannot connect to the Docker daemon at %s. Is the docker daemon running?", c.host)
		}
	}
	return fmt.Errorf("error during connect: %w", err)
}

func (c *Client) daemonError(resp *http.Response, body []byte) error {
	message := strings.TrimSpace(string(body))
	if strings.HasPrefix(resp.Header.Get("Content-Type"), "application/json") {
		var payload struct {
			Message string `json:"message"`
		}
		if err := json.Unmarshal(body, &payload); err == nil && payload.Message != "" {
			message = payload.Message
		}
	}
	return fmt.Errorf("Error response from daemon: %s", message)
}
