{"command":"cd /workspace && cat > cmd/common.go <<'EOF'
package cmd

import (
	"fmt"
	"os"
	"os/signal"
	"strings"
	"syscall"
	"time"

	"github.com/spf13/cobra"

	"hostctl/internal/hosts"
	"hostctl/internal/render"
)

// flag helpers tolerant to flags not defined on the command (needed because
// post actions run a different command with the flags of the caller).

func getString(cmd *cobra.Command, name string) string {
	v, _ := cmd.Flags().GetString(name)
	return v
}

func getBool(cmd *cobra.Command, name string) bool {
	v, _ := cmd.Flags().GetBool(name)
	return v
}

func getStringSlice(cmd *cobra.Command, name string) []string {
	v, _ := cmd.Flags().GetStringSlice(name)
	return v
}

func hostsFile(cmd *cobra.Command) string {
	return getString(cmd, "host-file")
}

func isQuiet(cmd *cobra.Command) bool {
	return getBool(cmd, "quiet")
}

func outputType(cmd *cobra.Command) string {
	out := getString(cmd, "out")
	if getBool(cmd, "raw") {
		out = "raw"
	}
	return out
}

func printHostsFileInfo(cmd *cobra.Command) error {
	if isQuiet(cmd) || getString(cmd, "out") == "json" {
		return nil
	}
	src := hostsFile(cmd)
	if src != defaultHostsFile || os.Getenv("HOSTCTL_FILE") != "" {
		fmt.Printf("[ℹ] Using hosts file: %s\n\n", src)
	}
	return nil
}

func printSuccess(format string, args ...interface{}) {
	fmt.Printf("[✔] "+format+"\n\n", args...)
}

func containsArg(args []string, value string) bool {
	for _, a := range args {
		if a == value {
			return true
		}
	}
	return false
}

// argument validators

func checkDefaultProfile(args []string) error {
	if containsArg(args, hosts.DefaultName) {
		return hosts.ErrDefaultProfile
	}
	return nil
}

// profilesArgs validates commands accepting several profiles or --all.
func profilesArgs(cmd *cobra.Command, args []string) error {
	all := getBool(cmd, "all")
	if all && len(args) > 0 {
		return hosts.ErrArgsWithAll
	}
	if !all && len(args) == 0 {
		return hosts.ErrMissingProfile
	}
	return checkDefaultProfile(args)
}

// singleProfileArgs validates commands accepting exactly one profile.
func singleProfileArgs(cmd *cobra.Command, args []string) error {
	if len(args) == 0 {
		return hosts.ErrMissingProfile
	}
	if len(args) > 1 {
		return hosts.ErrOnlyOneProfile
	}
	return checkDefaultProfile(args)
}

// profileAndDomainsArgs validates commands taking a profile followed by
// domains.
func profileAndDomainsArgs(cmd *cobra.Command, args []string) error {
	if len(args) == 0 {
		return hosts.ErrMissingProfile
	}
	return checkDefaultProfile(args)
}

// rendering helpers

func newRenderer(cmd *cobra.Command, columns []string) render.Renderer {
	return render.New(render.Options{
		Writer:  os.Stdout,
		Type:    outputType(cmd),
		Columns: columns,
	})
}

type profileFilter struct {
	names  []string
	status hosts.Status
}

func (f profileFilter) wantsName(name string) bool {
	return len(f.names) == 0 || containsArg(f.names, name)
}

func (f profileFilter) wantsStatus(status hosts.Status) bool {
	return f.status == "" || f.status == status
}

func appendProfileRows(r render.Renderer, p *hosts.Profile) {
	for _, key := range p.IPList {
		route := p.Routes[key]
		if route.IP == nil {
			continue
		}
		for _, h := range route.HostNames {
			r.AppendRow(render.Row{
				Profile: p.Name,
				Status:  string(p.Status),
				IP:      route.IP.String(),
				Host:    h,
			})
		}
	}
	r.Separator()
}

func appendDefaultRows(r render.Renderer, c *hosts.Content) {
	for _, l := range c.DefaultLines {
		if !l.IsRoute {
			continue
		}
		r.AppendRow(render.Row{
			Profile: hosts.DefaultName,
			Status:  string(l.Status()),
			IP:      l.IP.String(),
			Host:    l.Host,
		})
	}
	r.Separator()
}

// renderList prints the routes of the selected profiles.
func renderList(cmd *cobra.Command, c *hosts.Content, filter profileFilter) error {
	r := newRenderer(cmd, getStringSlice(cmd, "column"))

	if filter.wantsName(hosts.DefaultName) {
		appendDefaultRows(r, c)
	}

	for _, name := range c.ProfileNames {
		if !filter.wantsName(name) {
			continue
		}
		p, ok := c.Profiles[name]
		if !ok || !filter.wantsStatus(p.Status) {
			continue
		}
		appendProfileRows(r, p)
	}

	return r.Render()
}

// renderStatus prints the status of the selected profiles.
func renderStatus(cmd *cobra.Command, c *hosts.Content, names []string) error {
	r := newRenderer(cmd, render.StatusColumns)
	filter := profileFilter{names: names}

	for _, name := range c.ProfileNames {
		if !filter.wantsName(name) {
			continue
		}
		p, ok := c.Profiles[name]
		if !ok {
			continue
		}
		r.AppendRow(render.Row{Profile: p.Name, Status: string(p.Status)})
	}

	return r.Render()
}

// post actions

// setPostAction configures the hook executed after a command: it closes the
// output and, when --wait is given, runs the opposite command afterwards.
func setPostAction(cmd, post *cobra.Command) {
	cmd.PostRunE = func(c *cobra.Command, args []string) error {
		return postAction(c, args, post)
	}
}

func postAction(cmd *cobra.Command, args []string, post *cobra.Command) error {
	quiet := isQuiet(cmd)
	if !quiet {
		fmt.Println()
	}

	wait, err := cmd.Flags().GetDuration("wait")
	if err != nil || wait < 0 || post == nil {
		return nil
	}

	if !quiet {
		action := strings.TrimPrefix(post.CommandPath(), post.Root().Name()+" ")
		profiles := strings.Join(args, ", ")
		if wait == 0 {
			fmt.Printf("[ℹ] Waiting until ctrl+c to %s from profile '%s'\n\n\n", action, profiles)
		} else {
			fmt.Printf("[ℹ] Waiting for %s or ctrl+c to %s from profile '%s'\n\n\n", wait, action, profiles)
		}
	}

	waitSignalOrDuration(wait)
	fmt.Println()

	return post.RunE(cmd, args)
}

func waitSignalOrDuration(d time.Duration) {
	sig := make(chan os.Signal, 1)
	signal.Notify(sig, os.Interrupt, syscall.SIGTERM)
	defer signal.Stop(sig)

	if d == 0 {
		<-sig
		return
	}

	timer := time.NewTimer(d)
	defer timer.Stop()

	select {
	case <-sig:
	case <-timer.C:
	}
}

func addWaitFlag(cmd *cobra.Command, usage string) {
	cmd.Flags().DurationP("wait", "w", -1, usage)
}
