package cmd

import (
	"github.com/spf13/cobra"

	"hostctl/internal/hosts"
)

// newStatusChangeCmd builds the enable/disable commands which share the same
// behavior with opposite statuses.
func newStatusChangeCmd(status hosts.Status) *cobra.Command {
	name, opposite, short, long := "enable", "Disable", "Enable a profile on your hosts file.", `
Enables an existing profile.
It will be listed as "on" while it is enabled.
`
	if status == hosts.Disabled {
		name, opposite, short, long = "disable", "Enable", "Disable a profile from your hosts file.", `
Disable a profile from your hosts file without removing it.
It will be listed as "off" while it is disabled.
`
	}

	cmd := &cobra.Command{
		Use:   name + " [profiles]",
		Short: short,
		Long:  long,
		Args:  profilesArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			all := getBool(cmd, "all")
			only := getBool(cmd, "only")

			h, err := hosts.Open(hostsFile(cmd))
			if err != nil {
				return err
			}

			switch {
			case only:
				if all {
					h.Content.SetStatusAll(status)
				}
				h.Content.SetStatusOnly(args, status)
			case all:
				h.Content.SetStatusAll(status)
			default:
				if err := h.Content.SetStatus(args, status); err != nil {
					return err
				}
			}

			if err := h.Flush(); err != nil {
				return err
			}

			if isQuiet(cmd) {
				return nil
			}

			filter := profileFilter{names: args}
			if all {
				filter.names = nil
			}
			return renderList(cmd, h.Content, filter)
		},
	}

	title := strings.Title(name)
	cmd.Flags().Bool("all", false, title+" all profiles")
	cmd.Flags().Bool("only", false, opposite+" all other profiles")
	addWaitFlag(cmd, "Enables a profile for a specific amount of time")

	return cmd
}

func newEnableCmd() *cobra.Command {
	return newStatusChangeCmd(hosts.Enabled)
}

func newDisableCmd() *cobra.Command {
	return newStatusChangeCmd(hosts.Disabled)
}
