package cmd

import (
	"net"
	"os"
	"strings"

	"github.com/spf13/cobra"

	"hostctl/internal/hosts"
)

func newAddCmd(removeCmd *cobra.Command) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "add [profiles]",
		Short: "Add content to a profile in your hosts file.",
		Long: `
Reads from a file and set content to a profile in your hosts file.
If the profile already exists it will be added to it.
`,
		Args: singleProfileArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			return addFromFile(cmd, args[0], false)
		},
	}

	cmd.Flags().StringP("from", "f", "", "file to read")
	cmd.PersistentFlags().DurationP("wait", "w", -1, "Enables a profile for a specific amount of time. (example: 5m, 1h)")
	setPostAction(cmd, removeCmd)

	return cmd
}

func newReplaceCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "replace [profile]",
		Short: "Replace content to a profile in your hosts file.",
		Long: `
Reads from a file and set content to a profile in your hosts file.
If the profile already exists it will be overwritten.
`,
		Args: singleProfileArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			return addFromFile(cmd, args[0], true)
		},
	}

	cmd.Flags().StringP("from", "f", "", "file to read")

	return cmd
}

// addFromFile reads routes from the --from file and adds (or replaces) them
// into the named profile.
func addFromFile(cmd *cobra.Command, name string, replace bool) error {
	from := getString(cmd, "from")

	f, err := os.Open(from)
	if err != nil {
		return err
	}
	defer f.Close()

	h, err := hosts.Open(hostsFile(cmd))
	if err != nil {
		return err
	}

	p := hosts.ParseProfile(name, f)
	if replace {
