package cmd

import (
	"context"
	"os"
	"path/filepath"

	"github.com/spf13/cobra"

	"hostctl/internal/docker"
	"hostctl/internal/hosts"
)

const defaultDomain = "loc"

func newSyncCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "sync",
		Short: "Sync some system IPs with a profile.",
		Long: `
Reads IPs and names from some local system and sync it with a profile in your hosts file.
`,
	}

	cmd.PersistentFlags().DurationP("wait", "w", -1, "Enables a profile for a specific amount of time")

	return cmd
}

func dockerOptions(cmd *cobra.Command) docker.Options {
	domain := getString(cmd, "domain")
	if domain == "" {
		domain = defaultDomain
	}
	return docker.Options{
		Domain:  domain,
		Network: getString(cmd, "network"),
	}
}

func newSyncDockerCmd(removeCmd *cobra.Command) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "docker [profile]",
		Short: "Sync your Docker containers IPs with a profile.",
		Long: `
Reads from Docker the list of containers and add names and IPs to a profile in your hosts file.
`,
		Args: singleProfileArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			name := args[0]
			opts := dockerOptions(cmd)

			h, err := hosts.Open(hostsFile(cmd))
			if err != nil {
				return err
			}

			cli, err := docker.NewClientFromEnv()
			if err != nil {
				return err
			}

			ctx := context.Background()
			containers, networkID, err := cli.RunningContainers(ctx, opts.Network)
			if err != nil {
				return err
			}

			p := docker.ProfileFromContainers(name, containers, networkID, opts)
			h.Content.ReplaceProfile(p)

			if err := h.Flush(); err != nil {
				return err
			}

			if isQuiet(cmd) {
				return nil
			}
			return renderList(cmd, h.Content, profileFilter{names: []string{name}})
		},
	}

	cmd.Flags().StringP("domain", "d", defaultDomain, "domain where your docker containers will be added")
	cmd.Flags().String("network", "", "Filter containers from a specific network")
	setPostAction(cmd, removeCmd)

	return cmd
}

func newSyncDockerComposeCmd(removeCmd *cobra.Command) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "docker-compose [profile]",
		Short: "Sync your docker-compose containers IPs with a profile.",
		Long: `
Reads from a docker-compose.yml file  the list of containers and add names and IPs to a profile in your hosts file.
`,
		Args: singleProfileArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			name := args[0]
			opts := docker.ComposeOptions{
				Options:     dockerOptions(cmd),
				ProjectName: getString(cmd, "project-name"),
				KeepPrefix:  getBool(cmd, "prefix"),
			}
			composePath := getString(cmd, "compose-file")

			f, err := os.Open(composePath)
			if err != nil {
				return err
			}
			defer f.Close()

			h, err := hosts.Open(hostsFile(cmd))
			if err != nil {
				return err
			}

			cli, err := docker.NewClientFromEnv()
			if err != nil {
				return err
			}

			ctx := context.Background()
			containers, networkID, err := cli.RunningContainers(ctx, opts.Network)
			if err != nil {
				return err
			}

			services, err := docker.ParseCompose(f)
			if err != nil {
				return err
			}

			if opts.ProjectName == "" {
				opts.ProjectName = docker.ProjectName(composePath)
			}

			p := docker.ProfileFromCompose(name, containers, networkID, services, opts)
			h.Content.ReplaceProfile(p)

			return h.Flush()
		},
	}

	cwd, _ := os.Getwd()
	cmd.Flags().String("compose-file", filepath.Join(cwd, "docker-compose.yml"), "path to docker-compose.yml")
	cmd.Flags().StringP("domain", "d", defaultDomain, "domain where your docker containers will be added")
	cmd.Flags().String("network", "", "Filter containers from a specific network")
	cmd.Flags().Bool("prefix", false, "keep project name prefix from domain name")
	cmd.Flags().String("project-name", "", "docker compose project name")
	setPostAction(cmd, removeCmd)

	return cmd
}
EOF
