Reads from Docker the list of containers and add names and IPs to a profile in your hosts file.
`,
		Args: singleProfileArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			name := args[0]
			opts := dockerOptions(cmd)

			h, err := hosts.Open(hostsFile(cmd))
			if err != nil {
				return err
			}

			cli, err := docker.NewClientFromEnv()
			if err != nil {
				return err
			}

			ctx := context.Background()
			containers, networkID, err := cli.RunningContainers(ctx, opts.Network)
			if err != nil {
				return err
			}

			p := docker.ProfileFromContainers(name, containers, networkID, opts)
			h.Content.ReplaceProfile(p)

			if err := h.Flush(); err != nil {
				return err
			}

			if isQuiet(cmd) {
				return nil
			}
			return renderList(cmd, h.Content, profileFilter{names: []string{name}})
